2. Create a main Python script that:
   - Reads measurements.csv and computes statistics (mean, pop std dev, min, max)
   - Queries Wolfram|Alpha for integral of x^2 from 0 to 3 and 72 mph to m/s
   - Writes report.txt with marker string WA-AUDIT-2025
   - Writes summary.json with verified field
3. Run the script",
  "commands": [
    {
      "keystrokes": "cat > wolfram_query.py << 'EOF'
#!/usr/bin/env python3
"""Wolfram|Alpha query helper script."""
import sys
import os
import requests

def query_wolfram_alpha(query):
    """Query Wolfram|Alpha API and return the result."""
    app_id = os.environ.get('WOLFRAM_APP_ID')
    if not app_id:
        return None, "No WOLFRAM_APP_ID set"

    url = "https://api.wolframalpha.com/v1/result"
    params = {
        'appid': app_id,
        'input': query
    }

    try:
        response = requests.get(url, params=params, timeout=30)
        if response.status_code == 200:
            return response.text, None
        else:
            return None, f"API error: {response.status_code}"
    except Exception as e:
        return None, str(e)

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python3 wolfram_query.py <query>")
        sys.exit(1)

    query = " ".join(sys.argv[1:])
    result, error = query_wolfram_alpha(query)

    if error:
        print(f"Error: {error}")
        sys.exit(1)
    else:
        print(result)
EOF
